103	     1	// Pure Markdown assembly for the plan document (no I/O, so lib/assemble.test.ts can run it with node --test).
104	     2	export type Decision = { id: string; title: string; body: string; source: string | null };
105	     3	export type ImageInput = { id: string; title: string; url: string; source: string | null };
106	     4	
107	     5	export const SECTIONS = ['개요', '핵심 재미', '코어 루프', '주요 시스템', '아트·분위기', '결정 로그', '열린 질문/리스크', '다음 단계'] as const;
108	     6	
109	     7	const FALLBACK_TITLE = '이름 미정 게임';
110	     8	
111	     9	/** Escape a value for one GFM table cell: one line, pipes escaped. */
112	    10	export function cell(text: string): string {
113	    11	  return text.replace(/\s*\r?\n\s*/g, ' ').replace(/\\/g, '\\\\').replace(/\|/g, '\\|').trim() || '-';
114	    12	}
115	    13	
116	    14	/** `![caption](url)` with the caption and URL made safe for Markdown. */
117	    15	export function imageMd(img: Pick<ImageInput, 'title' | 'url'>): string {
118	    16	  const alt = img.title.replace(/\s+/g, ' ').replace(/([[\]\\])/g, '\\$1').trim() || '이미지';
119	    17	  return `![${alt}](${mdUrl(img.url)})`;
120	    18	}
121	    19	
122	    20	const mdUrl = (url: string) => url.replace(/[\s()<>]/g, (c) => encodeURIComponent(c));
123	    21	
124	    22	export function sourceLabel(source: string | null): string {
125	    23	  if (!source) return '직접 입력';
126	    24	  if (source === 'seed') return '예시';
127	    25	  if (source === 'upload' || source === 'manual') return '직접 입력';
128	    26	  if (source.startsWith('wf:')) return '워크플로우';
129	    27	  if (source.startsWith('step1:')) return 'Step1';
130	    28	  return source;
131	    29	}
132	    30	
133	    31	const plain = (line: string) => line.replace(/^\s*(?:[-*+]|\d+[.)])\s+/, '').replace(/\*\*|__|`/g, '').trim();
134	    32	
135	    33	/** `키: 값` lines (also `- **키**: 값`) from a decision body. */
136	    34	function keyValues(body: string): Map<string, string> {
137	    35	  const out = new Map<string, string>();
138	    36	  for (const raw of body.split('\n')) {
139	    37	    const m = plain(raw).match(/^([^:：]{1,20})[:：]\s*(.+)$/);
140	    38	    if (m) out.set(m[1].trim(), m[2].trim());
141	    39	  }
142	    40	  return out;
143	    41	}
144	    42	
145	    43	function find(decisions: Decision[], keys: string[]): string | undefined {
146	    44	  for (const d of decisions) {
147	    45	    const kv = keyValues(d.body);
148	    46	    for (const k of keys) if (kv.get(k)) return kv.get(k);
149	    47	  }
150	    48	}
151	    49	
152	    50	const has = (d: Decision, words: string[]) => words.some((w) => d.title.includes(w));
153	    51	
154	    52	/** First line of a decision that reads as its conclusion. */
155	    53	export function summary(d: Decision): string {
156	    54	  const lines = d.body.split('\n').map(plain).filter((l) => l && !l.startsWith('#'));
157	    55	  const line = lines.find((l) => /^결정\s*[:：]/.test(l)) ?? lines[0] ?? d.title;
158	    56	  return line.replace(/^결정\s*[:：]\s*/, '') || d.title;
159	    57	}
160	    58	
161	    59	export function gameTitle(decisions: Decision[], fallback?: string): string {
162	    60	  return find(decisions, ['가제', '게임 이름', '제목']) ?? (fallback?.trim() || FALLBACK_TITLE);
163	    61	}
164	    62	
165	    63	/** Lines tagged as open questions or risks, or lines that end in a question mark. */
166	    64	function openItems(decisions: Decision[]): string[] {
167	    65	  const out: string[] = [];
168	    66	  for (const d of decisions) {
169	    67	    for (const raw of d.body.split('\n')) {
170	    68	      const l = plain(raw);
171	    69	      if (l.startsWith('#')) continue;
172	    70	      const tagged = l.match(/^(열린 질문|질문|리스크|미정)[:：]\s*(.+)$/);
173	    71	      if (tagged) out.push(`${tagged[1] === '리스크' ? '리스크' : '질문'}: ${tagged[2]} (${d.title})`);
174	    72	      else if (/[?？]$/.test(l)) out.push(`질문: ${l} (${d.title})`);
175	    73	    }
176	    74	  }
177	    75	  return [...new Set(out)];
178	    76	}
179	    77	
180	    78	/** Loop steps from the loop decision: its numbered list, or a one-line `A → B → C` summary (workflow-view style). */
181	    79	export function loopSteps(decisions: Decision[]): string[] {
182	    80	  const d = decisions.find((x) => has(x, ['루프', '흐름']));
183	    81	  if (!d) return [];
184	    82	  const numbered = d.body.split('\n').filter((l) => /^\s*\d+[.)]\s+/.test(l)).map(plain);
185	    83	  if (numbered.length) return numbered;
186	    84	  const arrows = summary(d).split(/\s*(?:→|->|⟶|⇒)\s*/).map((x) => x.replace(/[.。]+$/, '').trim()).filter(Boolean);
187	    85	  return arrows.length > 1 ? arrows : [];
188	    86	}
189	    87	
190	    88	/** `결정: X` reads as X inside prose sections. */
191	    89	const unlabel = (text: string) => text.replace(/^(\s*(?:[-*+]\s+)?)결정\s*[:：]\s*/gm, '$1');
192	    90	
193	    91	/** Body without the `키: 값` lines already shown elsewhere. */
194	    92	function bodyRest(body: string, drop: string[]): string {
195	    93	  return body
196	    94	    .split('\n')
197	    95	    .filter((l) => !drop.some((k) => new RegExp(`^${k}\\s*[:：]`).test(plain(l))))
198	    96	    .join('\n')
199	    97	    .trim();
200	    98	}
201	    99	
202	   100	const OVERVIEW_KEYS = ['가제', '게임 이름', '제목', '한 줄 소개', '장르', '플랫폼', '타깃'];
203	   101	const OPEN_KEYS = ['열린 질문', '질문', '리스크', '미정'];
204	   102	
205	   103	/** Deterministic plan document built only from the given inputs. */
206	   104	export function assemble(decisions: Decision[], images: ImageInput[], fallbackTitle?: string): { title: string; markdown: string } {
207	   105	  const title = gameTitle(decisions, fallbackTitle);
208	   106	  const pick = (keys: string[]) => find(decisions, keys) ?? '아직 정하지 않았어요';
209	   107	  const loopDec = decisions.find((x) => has(x, ['루프', '흐름']));
210	   108	  const artDecs = decisions.filter((x) => has(x, ['아트', '분위기', '비주얼']));
211	   109	  const funDecs = decisions.filter((x) => has(x, ['재미', '콘셉트', '컨셉']));
212	   110	  // A decision whose body is only overview lines (가제, 장르, ...) already lives in 개요.
213	   111	  const detail = (x: Decision) => bodyRest(x.body, [...OVERVIEW_KEYS, ...OPEN_KEYS, '결정']);
214	   112	  const systemDecs = decisions.filter((x) => x !== loopDec && !artDecs.includes(x) && detail(x));
215	   113	  const funFrom = funDecs.length ? funDecs : decisions.filter((x) => x !== loopDec && detail(x));
216	   114	
217	   115	  const md: string[] = [`# ${title} 기획서`, ''];
218	   116	
219	   117	  md.push('## 개요', '');
220	   118	  md.push(`- 한 줄 소개: ${pick(['한 줄 소개', '한 줄 요약'])}`);
221	   119	  md.push(`- 장르: ${pick(['장르'])}`);
222	   120	  md.push(`- 플랫폼: ${pick(['플랫폼'])}`);
223	   121	  md.push(`- 타깃: ${pick(['타깃', '대상'])}`, '');
224	   122	
225	   123	  md.push('## 핵심 재미', '');
226	   124	  const fun = (funFrom.length ? funFrom : decisions).map((d) => `- ${summary(d)}`);
227	   125	  md.push(...(fun.length ? fun : ['- 결정 문서가 없어요. 결정을 하나 이상 고른 뒤 다시 만들어 주세요.']), '');
228	   126	
229	   127	  md.push('## 코어 루프', '');
230	   128	  const steps = loopSteps(decisions);
231	   129	  if (steps.length) md.push(...steps.map((s, i) => `${i + 1}. ${s}`), '');
232	   130	  else md.push('1. 아직 정하지 않았어요. 코어 루프를 정한 결정 문서(제목에 루프나 흐름)를 추가해 주세요.', '');
233	   131	
234	   132	  md.push('## 주요 시스템', '');
235	   133	  if (!systemDecs.length) md.push('주요 시스템을 다룬 결정 문서가 아직 없어요.', '');
236	   134	  for (const d of systemDecs) {
237	   135	    const rest = unlabel(bodyRest(d.body, [...OVERVIEW_KEYS, ...OPEN_KEYS])).replace(/^#{1,6}\s/gm, '#### ');
238	   136	    md.push(`### ${d.title}`, '', rest || summary(d), '');
239	   137	  }
240	   138	
241	   139	  md.push('## 아트·분위기', '');
242	   140	  const artText = artDecs.map((d) => unlabel(bodyRest(d.body, OPEN_KEYS)).replace(/^#{1,6}\s/gm, '#### ')).filter(Boolean);
243	   141	  for (const t of artText) md.push(t, '');
244	   142	  if (!artText.length && !images.length) md.push('아트 방향을 정한 결정이나 이미지가 아직 없어요.', '');
245	   143	  for (const img of images) md.push(imageMd(img), '');
246	   144	
247	   145	  md.push('## 결정 로그', '', '| 항목 | 결정 | 출처 |', '| --- | --- | --- |');
248	   146	  for (const d of decisions) md.push(`| ${cell(d.title)} | ${cell(summary(d))} | ${cell(sourceLabel(d.source))} |`);
249	   147	  if (!decisions.length) md.push('| - | 선택한 결정 문서가 없어요 | - |');
250	   148	  md.push('');
251	   149	
252	   150	  md.push('## 열린 질문/리스크', '');
253	   151	  const open = openItems(decisions);
254	   152	  md.push(...(open.length ? open.map((o) => `- ${o}`) : ['- 결정 문서에서 열린 질문을 찾지 못했어요. 검토할 때 채워 주세요.']), '');
255	   153	
256	   154	  md.push('## 다음 단계', '');
257	   155	  const next = ['결정 로그를 팀과 함께 검토하고 빠진 결정을 채우기', '코어 루프 한 바퀴를 종이 프로토타입으로 돌려 보기'];
258	   156	  if (open.length) next.push('열린 질문마다 담당자와 답할 날짜 정하기');
259	   157	  if (!images.length) next.push('아트 레퍼런스 이미지를 모아 분위기 정하기');
260	   158	  md.push(...next.map((s, i) => `${i + 1}. ${s}`), '');
261	   159	
262	   160	  return { title, markdown: md.join('\n') };
263	   161	}
