265	   163	/** Section names missing from a Markdown document (H1 `… 기획서` counts as `title`). */
266	   164	export function missingSections(markdown: string): string[] {
267	   165	  const heads = markdown.split('\n').filter((l) => /^##\s/.test(l)).map((l) => l.replace(/^##\s+/, ''));
268	   166	  const missing: string[] = SECTIONS.filter((s) => !heads.some((h) => h.includes(s)));
269	   167	  if (!/^#\s+.+기획서\s*$/m.test(markdown)) missing.unshift('title');
270	   168	  return missing;
271	   169	}
272	   170	
273	   171	/** Make sure every image is embedded: missing ones go at the end of the 아트·분위기 section. */
274	   172	export function ensureImages(markdown: string, images: ImageInput[]): string {
275	   173	  const absent = images.filter((img) => !markdown.includes(`](${mdUrl(img.url)}`));
276	   174	  if (!absent.length) return markdown;
277	   175	  const block = absent.map(imageMd).join('\n\n');
278	   176	  const lines = markdown.split('\n');
279	   177	  const art = lines.findIndex((l) => /^##\s.*아트/.test(l));
280	   178	  if (art < 0) return `${markdown.trimEnd()}\n\n## 아트·분위기\n\n${block}\n`;
281	   179	  let end = lines.findIndex((l, i) => i > art && /^##\s/.test(l));
282	   180	  if (end < 0) end = lines.length;
283	   181	  lines.splice(end, 0, block, '');
284	   182	  return lines.join('\n');
285	   183	}
